import{_ as t,c as l,o as e,a1 as r}from"./chunks/framework.4TBoba-N.js";const o="/images/fragmentation/External_Fragmentation.png",i="/images/fragmentation/Internal_Fragmentation.png",b=JSON.parse('{"title":"[CS] フラグメンテーションに対して","description":"メモリ管理のフラグメンテーションとGo言語のメモリアロケータ（TCMalloc/SLUB）についての解説","frontmatter":{"title":"[CS] フラグメンテーションに対して","description":"メモリ管理のフラグメンテーションとGo言語のメモリアロケータ（TCMalloc/SLUB）についての解説","date":"2026-03-17T10:41:12.000Z","lang":"ja","categories":["develop","CS"],"tags":["Go","CS","OS","Memory","Japanese"]},"headers":[],"relativePath":"post/memory-fragmentation/index.md","filePath":"posts/memory-fragmentation/index.md"}'),n={name:"post/memory-fragmentation/index.md"};function p(c,a,h,d,s,u){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="cs-フラグメンテーションに対して" tabindex="-1">[CS] フラグメンテーションに対して <a class="header-anchor" href="#cs-フラグメンテーションに対して" aria-label="Permalink to &quot;[CS] フラグメンテーションに対して&quot;">​</a></h1><hr><p><em>本ポストは韓国人が書いたポストであります。</em><em>もし文法の方や、言葉におかしいなところがあったらぜひ教えてください！</em></p><hr><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><hr><p>Go言語のメモリ管理によって、フラグメンテーションに対して触れることができた。</p><p>外部断片化や、内部断片化に対して学び、勉強しながら発生した疑問点に対して記録をするために書いておきたいと思ってます。</p><h2 id="内容" tabindex="-1">内容 <a class="header-anchor" href="#内容" aria-label="Permalink to &quot;内容&quot;">​</a></h2><hr><h3 id="external-fragmentation" tabindex="-1">External Fragmentation <a class="header-anchor" href="#external-fragmentation" aria-label="Permalink to &quot;External Fragmentation&quot;">​</a></h3><p>メモリを確保する時や、開放する時、与えられたメモリの間に使用ができない場合がある。</p><p>空いてる空間があるので、この空間を使えないのが External Fragmentation ではある。</p><p>トータルで空いてる空間の合計ではメモリを使用しても良いが、その空間が分けられているとしたら大きいメモリ要求ができないのである、、</p><p><img src="'+o+'" alt="External_Fragmentation.png"></p><p>なのでOS単位ではMemory圧縮や、Paging方法を使用するのだ。</p><h3 id="internal-fragmentation" tabindex="-1">Internal Fragmentation <a class="header-anchor" href="#internal-fragmentation" aria-label="Permalink to &quot;Internal Fragmentation&quot;">​</a></h3><p>メモリ確保や、プロセスが要求した大きさよりもっと大きい固定大きさのメモリブロックを確保すると使えないエリアーが作られる。</p><p>例えば10KBが必要な時に16KBを確保すると6KBは使えないです。</p><p>なのでSlab Allocatorみたいに要求された大きさに一番近いメモリブロックを細分化して確保方式を使用する！</p><p><img src="'+i+'" alt="Internal_Fragmentation.png"></p><p>だがこの文章の中で 「Slab Allocatorみたいに」 と言うことに対して少し深掘りをしてみよう。</p><hr><h3 id="slab-allocator" tabindex="-1">Slab Allocator <a class="header-anchor" href="#slab-allocator" aria-label="Permalink to &quot;Slab Allocator&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">INFO</p><p>💡 OSのカーナルや、高性能メモリ管理ライブラリ等に使う効率的なメモリ確保方式！ 単によく使っている大きさをお先に用意しとく方式だと理解すればしやすい！</p></div><p>まずこの概念を勉強する前に三つの構造に集中してみよう。</p><ul><li>キャッシュ → 特定の大きさのオブジェクトのための管理者</li><li>スラブ(Slab) → キャッシュがOSから確保された実際のメモリチャンク（多数のページ）！</li><li>スロット / オブジェクト (Slot/Object) → Slabを一定な大きさで切ったメモリの破片</li></ul><p>このSlab Allocatorは下のように動作します。</p><ol><li>Look-up</li></ol><p>プロセスが特定の大きさのメモリを要求すると、Slab Allocatorはこの大きさを受け取れる一番近い大きさのキャッシュを探します。</p><ul><li>Ex) 48 byte 要求 → 64 byte Cache</li></ul><ol><li>State Check</li></ol><p>キャッシュの中のSlabのStateを確認する！</p><ul><li>FULL : 全てのスロットが使用中</li><li>Partial：一部のスロットは使用中だが、一部は空いてる（優先順位）</li><li>Empty：全てのスロットが空いてる</li></ul><ol><li>Allocation</li></ol><ul><li>Partial Slabがあればその中に空いてるSlotをプロセスにすぐ与えます。 <ul><li>ここで検索時間がほぼ０です！</li></ul></li><li>PartialがなくEmtpy Slabだけあれば、そのSlabをPartial Stateに変更し、確保します。</li><li>全てのSlabがFullであれば、上位システム（Buddy System等）から新しいページをもらい、新しいSlabを作ります。</li></ul><p>そしたらなぜこのようなSlab Allocatorがフラグメンテーションの方法で使われているのか！</p><p>まず先ほどExternal Fragmentationに対して学びましたが、Slab Allocatorは細分化をして一定な大きさで確保しておきます！</p><p>なのでExternal Fragmentationが発生されないです！</p><p>Ex)</p><ul><li>8KB 欲しい → 8KBのメモリ領域確保</li><li>4KB 欲しい → 4KBのメモリ領域確保</li></ul><p>そして速度改善の部分がある。</p><p>毎回メモリのどこに入れるか計算する必要がなく、先に切っておいたスロットをすぐ渡せばいいのだ！</p><p>最後にキャッシュの効率が高いと言う部分だ。</p><p>同一な大きさのオブジェクトが物理的に近いところに集まっており、CPUのキャッシュ的中率が上がります！</p><hr><p>ここで疑問なのが一つある。</p><blockquote><p>空いてる空間があるって言うのをどうやって確認するのか？</p></blockquote><p>二つの方式で</p><ol><li>Free List</li><li>Bit Map</li></ol><p>上の二つの方式で把握するのである！</p><h4 id="free-list" tabindex="-1">Free List <a class="header-anchor" href="#free-list" aria-label="Permalink to &quot;Free List&quot;">​</a></h4><p>空いてるメモリブロックをLinked Listで繋がり、管理する方式です。</p><p>各空いてるブロックは次のブロックのアドレスを指すポインターを含めています。</p><p>確保が必要でしたら、Listの一番先（Head）のブロックを出してあげ、開放されたらまたListに繋がります。</p><p>速度が速いと言う良いところがありますが、リストを探索していくとお互い離れている空いてる空間がつながっていて、連続の大きい空間を探しづらいと言う特徴があります。</p><p>なので探索過程で空いてる空間を把握できるようになります！</p><h4 id="bit-map" tabindex="-1">Bit Map <a class="header-anchor" href="#bit-map" aria-label="Permalink to &quot;Bit Map&quot;">​</a></h4><p>メモリを一定の大きさのブロックで分け、各ブロックのStateを０か１で表現する方式であります！</p><p>０は空いてる空間であり、１は使用してる空間という意味です。</p><p>ビットで管理しているので、State記録にかかるメモリがすごく低いですが、空いてる空間を探すためにBit Arrayを最初からスキャンするので、メモリが大きくなるほど探索速度が遅い可能性があります！</p><h2 id="それではなぜgo言語でこのような内容が必要なのか" tabindex="-1">それではなぜGo言語でこのような内容が必要なのか？ <a class="header-anchor" href="#それではなぜgo言語でこのような内容が必要なのか" aria-label="Permalink to &quot;それではなぜGo言語でこのような内容が必要なのか？&quot;">​</a></h2><hr><p>Goのメモリ確保原理はGoogleが作ったTCMallocに基づいて設計されました。</p><p>これはSlab Allocatorの上位バージョンで理解できるんですが、その原理は下のようになります！</p><ol><li>mspanの登場</li></ol><p>Slab Allocatorでメモリ一を定な大きさで切ったチャンクをSlabと呼びました！</p><p>ですがGo言語ではこれが<code>mspan</code>だと言っております！</p><p>Page （８KB）を一つや多数組んで作ったメモリブロックです。</p><p>Goでは役67個のSpan Class ( Size Class ) を持ちます！　（8B ~ 32KB まで）</p><p>要求されたオブジェクトの大きさで一番近いSpan Classを探してそのmspanの中の空いてるスロットを確保します。</p><p>なので先ほどSlabの細分化と同じ戦略を使います！</p><ol><li>Lockがない確保</li></ol><p>一般的なSlab Allocatorは多数のスレッドが同時にメモリに要求するとLock問題が発生される可能性があります！</p><p>Goはこれを解決するためにLayer Architectureを使用します。</p><ul><li>mcache （Per-p Cache ） <ul><li>プロセス毎で持っているローカルキャッシュです。</li><li>Lockが必要ないのですごく速いです！</li></ul></li><li>mcentral （中央共有） <ul><li>mcacheに空いてるスロットがないとここでmspanを持ってきます！</li><li>多数のプロセスが共有するのでLockが必要です、、</li></ul></li><li>mheap （巨大Heap） <ul><li>システム全体の巨大なメモリストレージです。</li><li>mcentralでもメモリがないとここでページ単位で新しく確保されます！</li></ul></li></ul><ol><li>空いてる空間確認：ビットマップ使用</li></ol><p>Goではmspan内部でどんなスロットが空いてるか確認する時にBit Mapを使用します！</p><p>CPUのビット連山コマンドを利用して、空いてる空間を一瞬で探せます！</p><p>簡単にどのような差があるのか表で洗わせてみました！</p><table tabindex="0"><thead><tr><th>比較項目</th><th>Slab Allocator</th><th>Go Memory Allocator</th></tr></thead><tbody><tr><td>最低単位</td><td>Slot ( Object Size )</td><td>Object ( Span Class 基準）</td></tr><tr><td>管理単位</td><td>Slab</td><td>mspan</td></tr><tr><td>Layer Architecture</td><td>普通 1/2 Layer ( Local CPU Cache → Shared Cache )</td><td>3段階 Layer ( mcache → mcentral → mheap )</td></tr><tr><td>Parallel 処理</td><td>Lock Contention 発生可能性がある</td><td>Lock Free ( mcacheのおかげで性能優里）</td></tr><tr><td>メモリ記録</td><td>主にFree List</td><td>Bit Map ( allocBits )</td></tr></tbody></table><p>だが現在Linuxで使ってるのはSlubです！</p><h3 id="slub" tabindex="-1">SLUB <a class="header-anchor" href="#slub" aria-label="Permalink to &quot;SLUB&quot;">​</a></h3><p>Slabは性能を高めるためにかくCPUでオブジェクトQueueをおいて複雑に管理しました。</p><p>だがシステムのCPUコアが数十、数百回で増えて管理用データ（MetaData）自体がメモリをたくさん確保する問題がありました。</p><p>これを解決するためにSlubが現れました。</p><ul><li>Metadataの単純化 <ul><li>SlabはSlabの状態を管理するために別の複雑なStructを使いました。</li><li>だがSlubはLinuxの基本ページのStructをそのまま活用します。</li></ul></li><li>Queue削除 <ul><li>複雑なQueueを消して、現在使用しているSlabをむくポインターだけ維持して構造がすごく軽いです！</li></ul></li><li>性能最適化 <ul><li>大規模マルチーコアシステムでメモリOverheadが少ないし、キャッシュの効率がいいです！</li></ul></li></ul><p>上の特徴を見た時、GoのメモリAllocatorがSlubと似ていると思いました！</p><h2 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to &quot;結論&quot;">​</a></h2><hr><p>内容的には勉強用で書いてたんですけど、実際に書きながら自分も疑問になる瞬間があって、それを納得できるまで勉強になる過程でした。</p><p>この内容でもまだ書いてないところや、勉強が足りない部分があるんだと思いますが、これは就職活動が終わった後で深掘りをもっとしようと思います！</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><hr><ul><li><a href="https://github.com/google/tcmalloc" target="_blank" rel="noreferrer">https://github.com/google/tcmalloc</a></li><li><a href="https://en.wikipedia.org/wiki/Page_(computer_memory)" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Page_(computer_memory)</a></li><li><a href="https://docs.google.com/document/d/1TTj4T2JO42uD5ID9e89oa0sLKhJYD0Y_kqxDv3I3XMw/edit?tab=t.0" target="_blank" rel="noreferrer">https://docs.google.com/document/d/1TTj4T2JO42uD5ID9e89oa0sLKhJYD0Y_kqxDv3I3XMw/edit?tab=t.0</a></li><li><a href="https://jiravvit.tistory.com/entry/linux-kernel-4-%EC%8A%AC%EB%9E%A9%ED%95%A0%EB%8B%B9%EC%9E%90" target="_blank" rel="noreferrer">https://jiravvit.tistory.com/entry/linux-kernel-4-슬랩할당자</a></li></ul><h2 id="author-contact" tabindex="-1">Author Contact <a class="header-anchor" href="#author-contact" aria-label="Permalink to &quot;Author Contact&quot;">​</a></h2><hr><ul><li>📫 <a href="mailto:sunja1472@gmail.com" target="_blank" rel="noreferrer">sunja1472@gmail.com</a></li><li>🐙 <a href="https://github.com/Sunja-An" target="_blank" rel="noreferrer">GitHub</a></li></ul>',98)])])}const S=t(n,[["render",p]]);export{b as __pageData,S as default};
